import { TreeDataNode } from '../types';
import { DataEntity, Value } from './interface';

function removeFromCheckedKeys(halfCheckedKeys: Set<Value>, checkedKeys: Set<Value>) {
  const filteredKeys = new Set<Value>();
  halfCheckedKeys.forEach((key) => {
    if (!checkedKeys.has(key)) {
      filteredKeys.add(key);
    }
  });
  return filteredKeys;
}

function fillCheck<TreeDataType extends TreeDataNode = TreeDataNode>(
  keys: Set<Value>,
  levelEntities: Map<number, Set<DataEntity<TreeDataType>>>,
  maxLevel: number,
  // istanbul ignore next
  getDisabled: (node: TreeDataType) => boolean = (node) => node.disabled || false,
  // istanbul ignore next
  getKey: (node: DataEntity<TreeDataType>) => Value = (node) => node.key,
) {
  const checkedKeys = new Set<Value>(keys);
  const halfCheckedKeys = new Set<Value>();
  const key2CheckedChildrenCount = new Map<Value, number>();

  // Add checked keys for all children
  for (let level = 0; level <= maxLevel; level++) {
    const entities = levelEntities.get(level);
    entities?.forEach((entity) => {
      const { node, children = [] } = entity;
      const key = getKey(entity);
      if (checkedKeys.has(key) && !getDisabled(node)) {
        children.filter((child) => !getDisabled(child.node)).forEach((child) => checkedKeys.add(getKey(child)));
      }
    });
  }

  // Add checked keys for all parents
  const visitedKeys = new Set<Value>();
  for (let level = maxLevel; level >= 0; level--) {
    const entities = levelEntities.get(level);
    entities?.forEach((entity) => {
      const { parent, node } = entity;

      let parentKey!: Value;
      if (parent) {
        parentKey = getKey(parent!);
        // const checkedChildrenCount = (parent.children || []).filter((child) => checkedKeys.has(getKey(child))).length;
        // key2CheckedChildrenCount.set(parentKey, checkedChildrenCount);
      }

      if (getDisabled(node) || !parent || visitedKeys.has(parentKey)) {
        return;
      }

      // skip if parent is disabled
      if (getDisabled(parent.node)) {
        visitedKeys.add(parentKey);
        return;
      }

      let allChecked = true;
      let partialChecked = false;

      let checkedCount = 0;
      (parent.children || []).forEach((childEntity) => {
        const key = getKey(childEntity);
        const checked = checkedKeys.has(key);
        if (checked) {
          checkedCount++;
        }
        if (getDisabled(childEntity.node)) {
          return;
        }
        if (allChecked && !checked) {
          allChecked = false;
        }
        if (!partialChecked && (checked || halfCheckedKeys.has(key))) {
          partialChecked = true;
        }
      });

      key2CheckedChildrenCount.set(parentKey, checkedCount);

      if (allChecked) {
        checkedKeys.add(parentKey);
      }
      if (partialChecked) {
        halfCheckedKeys.add(parentKey);
      }

      visitedKeys.add(parentKey);
    });
  }

  return {
    checkedKeys: Array.from(checkedKeys),
    halfCheckedKeys: Array.from(removeFromCheckedKeys(halfCheckedKeys, checkedKeys)),
    key2CheckedChildrenCount,
  };
}

function cleanCheck<TreeDataType extends TreeDataNode = TreeDataNode>(
  keys: Set<Value>,
  halfKeys: Value[],
  levelEntities: Map<number, Set<DataEntity<TreeDataType>>>,
  maxLevel: number,
  // istanbul ignore next
  getDisabled: (node: TreeDataType) => boolean = (node) => node.disabled || false,
  // istanbul ignore next
  getKey: (node: DataEntity<TreeDataType>) => Value = (node) => node.key,
) {
  const checkedKeys = new Set<Value>(keys);
  let halfCheckedKeys = new Set<Value>(halfKeys);
  const key2CheckedChildrenCount = new Map<Value, number>();

  // Remove checked keys for all children
  for (let level = 0; level <= maxLevel; level++) {
    const entities = levelEntities.get(level);
    entities?.forEach((entity) => {
      const { node, children = [] } = entity;
      const key = getKey(entity);
      if (!checkedKeys.has(key) && !halfCheckedKeys.has(key) && !getDisabled(node)) {
        children.filter((child) => !getDisabled(child.node)).forEach((child) => checkedKeys.delete(getKey(child)));
      }
    });
  }

  // Remove checked keys for all parents
  halfCheckedKeys = new Set<Value>();
  const visitedKeys = new Set<Value>();

  for (let level = maxLevel; level >= 0; level--) {
    const entities = levelEntities.get(level);

    entities?.forEach((entity) => {
      const { parent, node } = entity;

      let parentKey!: Value;
      if (parent) {
        parentKey = getKey(parent!);
        // const checkedChildrenCount = (parent.children || []).filter((child) => checkedKeys.has(getKey(child))).length;
        // key2CheckedChildrenCount.set(parentKey, checkedChildrenCount);
      }

      // skip if no need to check
      if (getDisabled(node) || !parent || visitedKeys.has(parentKey)) {
        return;
      }

      // skip if parent is disabled
      if (getDisabled(parent.node)) {
        visitedKeys.add(parentKey);
        return;
      }

      let allChecked = true;
      let partialChecked = false;

      let checkedCount = 0;
      (parent.children || []).forEach((childEntity) => {
        const key = getKey(childEntity);
        const checked = checkedKeys.has(key);
        if (checked) {
          checkedCount++;
        }
        if (getDisabled(childEntity.node)) {
          return;
        }
        if (allChecked && !checked) {
          allChecked = false;
        }
        if (!partialChecked && (checked || halfCheckedKeys.has(key))) {
          partialChecked = true;
        }
      });

      key2CheckedChildrenCount.set(parentKey, checkedCount);

      if (!allChecked) {
        checkedKeys.delete(parentKey);
      }
      if (partialChecked) {
        halfCheckedKeys.add(parentKey);
      }

      visitedKeys.add(parentKey);
    });
  }

  return {
    checkedKeys: Array.from(checkedKeys),
    halfCheckedKeys: Array.from(removeFromCheckedKeys(halfCheckedKeys, checkedKeys)),
    key2CheckedChildrenCount,
  };
}

interface CheckResult {
  checkedKeys: Value[];
  halfCheckedKeys: Value[];
  key2CheckedChildrenCount: Map<Value, number>;
}

export function processCheck<TreeDataType extends TreeDataNode = TreeDataNode>(
  keyList: Value[],
  checked: true | { checked: false; halfCheckedKeys: Value[] },
  keyEntities: Record<Value, DataEntity<TreeDataType>>,
  config?: {
    getDisabled?: (node: TreeDataType) => boolean;
    getKey?: (node: DataEntity<TreeDataType>) => Value;
  },
) {
  const {
    getDisabled = (node: TreeDataType) => node.disabled || false,
    getKey = (node: DataEntity<TreeDataType>) => node.key,
  } = config || {};

  const keys = new Set<Value>(
    keyList.filter((key) => {
      const hasEntity = !!keyEntities[key];
      return hasEntity;
    }),
  );

  const levelEntities = new Map<number, Set<DataEntity<TreeDataType>>>();
  let maxLevel = 0;

  Object.keys(keyEntities).forEach((key) => {
    const entity = keyEntities[key];
    if (entity) {
      const { level } = entity;

      maxLevel = Math.max(maxLevel, level);
      const entities = levelEntities.get(level) || new Set<DataEntity<TreeDataType>>();
      entities.add(entity);
      levelEntities.set(level, entities);
    }
  });

  let result: CheckResult;

  if (checked === true) {
    result = fillCheck(keys, levelEntities, maxLevel, getDisabled, getKey);
  } else {
    const { halfCheckedKeys: halfKeys } = checked;
    result = cleanCheck(keys, halfKeys, levelEntities, maxLevel, getDisabled, getKey);
  }

  return result;
}
